def test_loop_controls(self):
    env = Environment(extensions=["jinja2.ext.loopcontrols"])

    tmpl = env.from_string(
        """
        {%- for item in [1, 2, 3, 4] %}
            {%- if item % 2 == 0 %}{% continue %}{% endif -%}
            {{ item }}
        {%- endfor %}"""
    )
    assert tmpl.render() == "13"

    tmpl = env.from_string(
        """
        {%- for item in [1, 2, 3, 4] %}
            {%- if item > 2 %}{% break %}{% endif -%}
            {{ item }}
        {%- endfor %}"""
    )
    assert tmpl.render() == "12"

